const STR = {
  title: '拔塞过程三阶段：木塞相对瓶口基准线的位置',
  formula: 'u = x / h',
  cap0: 'u = 0',
  cap1: 'u = 1 / 2',
  cap2: 'u = 1',
  note0: '完全插入，底面在瓶口下 h 处',
  note1: '木塞上移 h / 2',
  note2: '木塞底面到达瓶口基准线',
  refLabel: '瓶口基准线',
  corkLabel: '木塞',
  hLabel: 'h',
  xLab0: 'x = 0',
  xLab1: 'x = h / 2',
  xLab2: 'x = h',
  legend1: 'u = x / h：u 为拔出进度，x 为木塞相对初始位置的上移位移，h 为木塞长度',
  legend2: '三阶段的瓶口基准线保持同一水平高度，木塞上移位移按真实比例 x = 0、h / 2、h 绘制。'
};
const ORDER = ['title', 'formula', 'cap0', 'cap1', 'cap2', 'note0', 'note1', 'note2', 'refLabel', 'corkLabel', 'hLabel', 'xLab0', 'xLab1', 'xLab2', 'legend1', 'legend2'];
const visual = {
  prepare: function (input) {
    var out = [];
    for (var i = 0; i < ORDER.length; i++) out.push({ kind: 'text', payload: STR[ORDER[i]] });
    return out;
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var ink = '#243447', gray = '#8d9aab', accent = '#b03a2e', corkCol = '#8a6a3f';
    var paths = [], children = [];

    function tw(key) {
      var i = ORDER.indexOf(key);
      if (i < 0 || !metrics) return 0;
      var m = metrics[i];
      if (!m) return 0;
      if (typeof m.width === 'number') return m.width;
      if (typeof m.w === 'number') return m.w;
      if (m.bbox && typeof m.bbox.width === 'number') return m.bbox.width;
      return 0;
    }
    function push(cmds, stroke, sw) {
      if (!cmds || !cmds.length) return;
      var id = 'p' + paths.length;
      paths.push({ id: id, commands: cmds });
      children.push({ type: 'path', pathId: id, stroke: stroke, strokeWidth: sw === undefined ? 2 : sw });
    }
    function label(key, x, y, fs, anchor, color) {
      children.push({ type: 'label', text: STR[key], x: x, y: y, fontSize: fs, textAnchor: anchor || 'middle', fill: color || ink });
    }
    function dashLine(x1, y1, x2, y2, dash, gap) {
      var cmds = [];
      var dx = x2 - x1, dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len < 0.5) return cmds;
      var ux = dx / len, uy = dy / len;
      var t = 0;
      while (t < len - 0.5) {
        var e = Math.min(t + dash, len);
        var seg = visualSdk.polyline([[x1 + ux * t, y1 + uy * t], [x1 + ux * e, y1 + uy * e]]);
        for (var k = 0; k < seg.length; k++) cmds.push(seg[k]);
        t += dash + gap;
      }
      return cmds;
    }
    function quad(p0, p1, p2, n) {
      var pts = [];
      for (var i = 0; i <= n; i++) {
        var t = i / n, mt = 1 - t;
        pts.push([mt * mt * p0[0] + 2 * mt * t * p1[0] + t * t * p2[0],
                  mt * mt * p0[1] + 2 * mt * t * p1[1] + t * t * p2[1]]);
      }
      return visualSdk.polyline(pts);
    }
    function roundRect(ccx, top, w, hh, r) {
      var x0 = ccx - w / 2, x1 = ccx + w / 2, y0 = top, y1 = top + hh;
      var seg = 5, pts = [];
      function corner(ax, ay, a0, a1) {
        for (var i = 0; i <= seg; i++) {
          var a = a0 + (a1 - a0) * i / seg;
          pts.push([ax + r * Math.cos(a), ay + r * Math.sin(a)]);
        }
      }
      corner(x0 + r, y0 + r, Math.PI, 1.5 * Math.PI);
      corner(x1 - r, y0 + r, 1.5 * Math.PI, 2 * Math.PI);
      corner(x1 - r, y1 - r, 0, 0.5 * Math.PI);
      corner(x0 + r, y1 - r, 0.5 * Math.PI, Math.PI);
      pts.push([pts[0][0], pts[0][1]]);
      return visualSdk.polyline(pts);
    }

    var margin = 22;
    var panelW = (W - margin * 2) / 3;
    var yM = Math.round(H * 0.48);
    var h = Math.round(H * 0.19);
    var neckDepth = Math.round(H * 0.30);
    var corkW = 34;
    var bottomY = yM + neckDepth;
    var us = [0, 0.5, 1];
    var capKeys = ['cap0', 'cap1', 'cap2'];
    var noteKeys = ['note0', 'note1', 'note2'];
    var xKeys = ['xLab0', 'xLab1', 'xLab2'];

    var tFS = 16;
    var twt = tw('title');
    if (twt > 0 && twt > W - 60) tFS = 13.5;
    label('title', W / 2, 26, tFS, 'middle', ink);
    label('formula', W / 2, 50, 14, 'middle', accent);

    for (var i = 0; i < 3; i++) {
      var cx = margin + panelW * (i + 0.5);
      var u = us[i];
      var wallL = cx - 24, wallR = cx + 24;
      var halfGap = panelW / 2 - 10;
      var top = yM - u * h;
      var xa = cx + 46;
      var y0 = yM + h;
      var y1 = yM + h - u * h;

      label(capKeys[i], cx, yM - h - 46, 16, 'middle', ink);
      label(noteKeys[i], cx, yM - h - 26, 11.5, 'middle', gray);

      push(dashLine(cx - halfGap, yM, cx - corkW / 2 - 5, yM, 7, 6), gray, 1.2);
      push(dashLine(cx + corkW / 2 + 5, yM, cx + halfGap, yM, 7, 6), gray, 1.2);
      if (i === 0) label('refLabel', cx - halfGap + 2, yM - 8, 10.5, 'start', gray);

      push(visualSdk.polyline([[wallL, yM + 3], [wallL, bottomY]]), ink, 2.2);
      push(visualSdk.polyline([[wallR, yM + 3], [wallR, bottomY]]), ink, 2.2);
      push(quad([wallL, bottomY], [wallL, bottomY + 16], [wallL - 26, bottomY + 22], 10), ink, 2);
      push(quad([wallR, bottomY], [wallR, bottomY + 16], [wallR + 26, bottomY + 22], 10), ink, 2);
      push(visualSdk.polyline([[wallL - 9, yM], [wallL + 3, yM]]), ink, 3);
      push(visualSdk.polyline([[wallR - 3, yM], [wallR + 9, yM]]), ink, 3);

      push(roundRect(cx, top, corkW, h, 7), corkCol, 2.4);
      label('corkLabel', cx, top + h / 2 + 3.5, 10, 'middle', corkCol);

      push(visualSdk.polyline([[xa - 12, y0], [xa + 12, y0]]), gray, 1.2);
      if (u > 0) {
        push(visualSdk.arrow(xa, y0, xa, y1, {}), accent, 1.6);
      } else {
        push(visualSdk.polyline([[xa - 7, y0 - 1], [xa + 7, y0 - 1]]), accent, 1.6);
      }
      label(xKeys[i], xa + 9, (u > 0 ? (y0 + y1) / 2 : y0) + 4, 12, 'start', accent);

      if (i === 0 || i === 2) {
        var xh = cx - 46;
        var hTop = (i === 0) ? yM : yM - h;
        var hBot = (i === 0) ? yM + h : yM;
        push(visualSdk.polyline([[xh - 7, hTop], [xh + 7, hTop]]), gray, 1.2);
        push(visualSdk.polyline([[xh - 7, hBot], [xh + 7, hBot]]), gray, 1.2);
        push(visualSdk.polyline([[xh, hTop], [xh, hBot]]), gray, 1.4);
        label('hLabel', xh - 9, (hTop + hBot) / 2 + 4, 13, 'end', gray);
      }
    }

    label('legend1', W / 2, H - 44, 12, 'middle', ink);
    label('legend2', W / 2, H - 24, 12, 'middle', gray);

    return {
      schemaVersion: 1,
      sceneId: 'stopper-pull-stages',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
